static class Grounder
{
    public static int LexCompare(List<int> a, List<int> b)
    {
        for (int i = 0; i < Math.Min(a.Count, b.Count); i++) if (a[i] != b[i]) return a[i].CompareTo(b[i]);
        return a.Count.CompareTo(b.Count);
    }
    public static bool Subtype(Domain domain, string type, string expected)
    {
        string current = type;
        while (true)
        {
            if (current == expected) return true;
            if (!domain.Parents.TryGetValue(current, out string? parent)) return false;
            current = parent;
        }
    }
    public static HashSet<string> Fluents(Domain domain) => domain.Actions.SelectMany(a => a.Effects.Select(l => l.Atom.Predicate)).ToHashSet(StringComparer.Ordinal);
    public static Grounding Ground(Domain domain, Problem problem)
    {
        HashSet<string> fluent = Fluents(domain);
        HashSet<Atom> initial = problem.Initial.ToHashSet();
        int[][] stats = domain.Actions.Select(_ => new int[3]).ToArray();
        List<GroundCandidate> candidates = new();
        for (int source = 0; source < domain.Actions.Count; source++)
        {
            Schema action = domain.Actions[source];
            List<List<string>> choices = action.Parameters.Select(p => problem.Objects.Where(o => Subtype(domain, o.Type, p.Type)).Select(o => o.Name).ToList()).ToList();
            List<List<string>> all = new();
            List<string> current = new();
            void Combinations(int i)
            {
                if (i == choices.Count) {
                    all.Add(new(current));
                    return;
                }
                foreach (string obj in choices[i]) {
                    current.Add(obj);
                    Combinations(i + 1);
                    current.RemoveAt(current.Count - 1);
                }
            }
            Combinations(0);
            stats[source][0] = all.Count;
            foreach (List<string> args in all)
            {
                Dictionary<string, string> values = action.Parameters.Select((p, i) => (p.Name, Value: args[i])).ToDictionary(p => p.Name, p => p.Value, StringComparer.Ordinal);
                GroundCandidate candidate = new(source, args);
                bool valid = true;
                foreach (Literal literal in action.Pre)
                {
                    Atom atom = literal.Atom.Replace(values);
                    if (atom.Predicate == "=" || !fluent.Contains(atom.Predicate))
                    {
                        bool truth = atom.Predicate == "=" ? atom.Terms[0] == atom.Terms[1] : initial.Contains(atom);
                        if (truth == literal.Negative) {
                            valid = false;
                            break;
                        }
                    }
                    else if (literal.Negative) candidate.Neg.Add(atom);
                    else candidate.Pre.Add(atom);
                }
                if (!valid) continue;
                foreach (Literal literal in action.Effects)
                {
                    Atom atom = literal.Atom.Replace(values);
                    if (literal.Negative) candidate.Del.Add(atom);
                    else candidate.Add.Add(atom);
                }
                candidate.Del.ExceptWith(candidate.Add);
                stats[source][1]++;
                candidates.Add(candidate);
            }
        }
        HashSet<Atom> reachable = initial.Where(a => fluent.Contains(a.Predicate)).ToHashSet();
        HashSet<int> kept = new();
        while (true)
        {
            int before = kept.Count;
            for (int i = 0; i < candidates.Count; i++) if (candidates[i].Pre.IsSubsetOf(reachable)) {
                kept.Add(i);
                reachable.UnionWith(candidates[i].Add);
            }
            if (kept.Count == before) break;
        }
        Dictionary<string, int> predicates = domain.Predicates.Select((p, i) => (p.Name, Index: i)).ToDictionary(p => p.Name, p => p.Index, StringComparer.Ordinal);
        Dictionary<string, int> objects = problem.Objects.Select((o, i) => (o.Name, Index: i)).ToDictionary(p => p.Name, p => p.Index, StringComparer.Ordinal);
        List<Atom> facts = reachable.OrderBy(a => predicates[a.Predicate]).ThenBy(a => a.Terms.Select(t => objects[t]).ToList(), Comparer<List<int>>.Create(LexCompare)).ToList();
        Dictionary<Atom, int> numbering = facts.Select((a, i) => (Atom: a, Index: i)).ToDictionary(p => p.Atom, p => p.Index);
        State Numbers(IEnumerable<Atom> atoms) => atoms.Where(numbering.ContainsKey).Select(a => numbering[a]).ToHashSet();
        List<GroundAction> actions = new();
        foreach (int i in kept.Order())
        {
            GroundCandidate c = candidates[i];
            Schema a = domain.Actions[c.Source];
            stats[c.Source][2]++;
            actions.Add(new GroundAction(c.Source, a.Name, c.Args, a.Cost, Numbers(c.Pre), Numbers(c.Neg), Numbers(c.Add), Numbers(c.Del)));
        }
        State goals = new();
        List<Atom> unreachable = new();
        foreach (Atom atom in problem.Goals)
        {
            if (numbering.TryGetValue(atom, out int i)) goals.Add(i);
            else if (fluent.Contains(atom.Predicate) || !initial.Contains(atom)) unreachable.Add(atom);
        }
        return new Grounding(facts, actions, Numbers(initial), goals, unreachable, stats, fluent, problem.Initial.Count(a => !fluent.Contains(a.Predicate)));
    }
}

sealed record Relaxed(long Value, List<int> Plan, List<int> Helpful);
static class Heuristics
{
    public const long Infinity = 1_000_000_000_000;
    static long Aggregate(IEnumerable<long> input, bool maximum)
    {
        List<long> values = input.ToList();
        return values.Any(v => v >= Infinity) ? Infinity : maximum ? values.DefaultIfEmpty(0).Max() : values.Sum();
    }
    static long[] Costs(Grounding g, State state, bool maximum)
    {
        long[] costs = Enumerable.Repeat(Infinity, g.Facts.Count).ToArray();
        foreach (int fact in state) costs[fact] = 0;
        while (true)
        {
            bool changed = false;
            foreach (GroundAction action in g.Actions)
            {
                long previous = Aggregate(action.Pre.Select(p => costs[p]), maximum);
                if (previous >= Infinity) continue;
                long value = previous + action.Cost;
                foreach (int fact in action.Add) if (value < costs[fact]) {
                    costs[fact] = value;
                    changed = true;
                }
            }
            if (!changed) return costs;
        }
    }
    public static Relaxed Relax(Grounding g, State state)
    {
        long[] costs = Costs(g, state, false);
        if (g.Goals.Any(p => costs[p] >= Infinity)) return new Relaxed(Infinity, new(), new());
        int Achiever(int fact) => Enumerable.Range(0, g.Actions.Count).Where(i => g.Actions[i].Add.Contains(fact) && g.Actions[i].Pre.All(p => costs[p] < Infinity)).OrderBy(i => g.Actions[i].Cost + g.Actions[i].Pre.Sum(p => costs[p])).ThenBy(i => i).First();
        State chosen = new();
        List<int> pending = g.Goals.Except(state).Order().ToList();
        while (pending.Count > 0)
        {
            int fact = pending[^1];
            pending.RemoveAt(pending.Count - 1);
            int action = Achiever(fact);
            if (chosen.Add(action)) pending.AddRange(g.Actions[action].Pre.Except(state).Order());
        }
        List<int> plan = chosen.Order().ToList();
        return new Relaxed(plan.Sum(i => (long)g.Actions[i].Cost), plan, plan.Where(i => Search.Applicable(g.Actions[i], state)).ToList());
    }
    public static State? Landmarks(Grounding g, State state)
    {
        int[] factLevel = Enumerable.Repeat(int.MaxValue, g.Facts.Count).ToArray(), actionLevel = Enumerable.Repeat(int.MaxValue, g.Actions.Count).ToArray();
        foreach (int fact in state) factLevel[fact] = 0;
        for (int k = 0; ; k++)
        {
            bool added = false;
            for (int i = 0; i < g.Actions.Count; i++) if (actionLevel[i] == int.MaxValue && g.Actions[i].Pre.All(p => factLevel[p] <= k))
            {
                actionLevel[i] = k;
                foreach (int fact in g.Actions[i].Add) if (factLevel[fact] == int.MaxValue) {
                    factLevel[fact] = k + 1;
                    added = true;
                }
            }
            if (!added) break;
        }
        if (g.Goals.Any(p => factLevel[p] == int.MaxValue)) return null;
        State landmarks = g.Goals.Except(state).ToHashSet();
        while (true)
        {
            int before = landmarks.Count;
            foreach (int fact in landmarks.Order().ToArray())
            {
                int[] achievers = Enumerable.Range(0, g.Actions.Count).Where(i => actionLevel[i] != int.MaxValue && actionLevel[i] + 1 == factLevel[fact] && g.Actions[i].Add.Contains(fact)).ToArray();
                State candidates = new(g.Actions[achievers[0]].Pre);
                foreach (int i in achievers.Skip(1)) candidates.IntersectWith(g.Actions[i].Pre);
                foreach (int candidate in candidates.Except(state).Order()) if (!landmarks.Contains(candidate))
                {
                    State reachable = new(state);
                    while (true)
                    {
                        int old = reachable.Count;
                        foreach (GroundAction a in g.Actions) if (!a.Add.Contains(candidate) && a.Pre.IsSubsetOf(reachable)) reachable.UnionWith(a.Add);
                        if (old == reachable.Count) break;
                    }
                    if (!g.Goals.IsSubsetOf(reachable)) landmarks.Add(candidate);
                }
            }
            if (before == landmarks.Count) return landmarks;
        }
    }
    public static long Value(Grounding g, State state, string name)
    {
        if (name == "none") return 0;
        if (name == "goalcount") return g.Goals.Except(state).Count();
        if (name is "hmax" or "hadd")
        {
            bool maximum = name == "hmax";
            long[] costs = Costs(g, state, maximum);
            return Aggregate(g.Goals.Select(p => costs[p]), maximum);
        }
        if (name == "ff") return Relax(g, state).Value;
        State? landmarks = Landmarks(g, state);
        return landmarks is null ? Infinity : landmarks.Count;
    }
    public static List<long> Values(Grounding g, State state) => new[] {
        "goalcount", "hmax", "hadd", "ff", "lmcount"
    }.Select(h => Value(g, state, h)).ToList();
}

